using Og.Core.Runtime;

namespace Og.Core.Tests;

/// <summary>
/// A wander-friendly world of its own: the shared fixture's monster room only
/// leads back to spawn, which is exactly the one place wandering must never
/// go, so it can't exercise the real move at all.
/// </summary>
public static class WanderFixture
{
    public const string Json = """
    {
      "name": "wander-fixture",
      "spawnLocation": 1,
      "startingItems": ["dagger"],
      "items": [
        { "name": "dagger", "description": "A short blade.", "kind": "weapon", "attackDice": 4 }
      ],
      "monsters": [
        { "name": "wolf", "description": "A wolf watches you.", "hitPoints": 7,
          "armorClass": 12, "attackStrength": 1, "attackDice": 6, "respawnSeconds": 60 }
      ],
      "locations": [
        {
          "index": 1,
          "name": "The Hollow",
          "description": "Spawn. There is a way north.",
          "connections": { "north": 2 }
        },
        {
          "index": 2,
          "name": "The Field",
          "description": "A field, open on three sides.",
          "connections": { "south": 1, "east": 3, "west": 4 },
          "monster": "wolf"
        },
        {
          "index": 3,
          "name": "The Clearing",
          "description": "A clearing east of the field.",
          "connections": { "west": 2 }
        },
        {
          "index": 4,
          "name": "The Grove",
          "description": "A grove west of the field.",
          "connections": { "east": 2 }
        },
        {
          "index": 5,
          "name": "The Gate",
          "description": "The only way out.",
          "isExit": true,
          "connections": { "east": 2 }
        }
      ]
    }
    """;

    public static World Build() => World.FromJson(Json);

    public static (GameEngine Engine, CollectingEventSink Events) NewEngine(int seed = 1234) =>
        (new GameEngine(Build(), new CollectingEventSink(), seed), new CollectingEventSink());
}

public class WanderTests
{
    private static Location MonsterLocation(GameEngine engine) =>
        engine.World.Locations.Single(location => location.Monster is { IsAlive: true });

    [Fact]
    public void AnUnwatchedMonsterEventuallyMovesToAnOpenNeighbour()
    {
        var events = new CollectingEventSink();
        var engine = new GameEngine(WanderFixture.Build(), events, seed: 1234);

        var moved = false;

        for (var tick = 0; tick < 100 && !moved; tick++)
        {
            engine.WanderMonsters();
            moved = MonsterLocation(engine).Id != 2;
        }

        Assert.True(moved, "a monster alone in a room, ticked 100 times at a 1-in-4 chance, never moved");

        // Exactly one monster exists anywhere in the world, same as before.
        Assert.Single(engine.World.Locations, location => location.Monster is { IsAlive: true });

        Assert.Contains(events.Events, e => e.Type == EventType.MonsterWandered);
    }

    [Fact]
    public void AMonsterNeverWandersIntoTheSpawnOrAnExit()
    {
        var (engine, _) = WanderFixture.NewEngine();

        for (var tick = 0; tick < 200; tick++)
        {
            engine.WanderMonsters();
            var at = MonsterLocation(engine).Id;
            Assert.NotEqual(1, at);
            Assert.NotEqual(5, at);
        }
    }

    [Fact]
    public void AMonsterDoesNotWanderAwayWhileSomeoneStandsWithIt()
    {
        var events = new CollectingEventSink();
        var engine = new GameEngine(WanderFixture.Build(), events, seed: 1234);
        var (alice, _) = WorldFixture.Join(engine, "Alice");
        engine.HandleInput(alice, "north");

        Assert.Equal(2, alice.CurrentLocationId);

        for (var tick = 0; tick < 100; tick++)
        {
            engine.WanderMonsters();
        }

        Assert.Equal(2, MonsterLocation(engine).Id);
    }

    [Fact]
    public void WanderingIsSilentWhenNobodyIsThereToSeeIt()
    {
        var events = new CollectingEventSink();
        var engine = new GameEngine(WanderFixture.Build(), events, seed: 1234);

        for (var tick = 0; tick < 100; tick++)
        {
            engine.WanderMonsters();
        }

        // No session ever received a message: nobody was present anywhere the
        // monster moved from or to.
        Assert.DoesNotContain(events.Events, e => e.Type == EventType.MonsterReturned);
    }
}

